/**
 * Supported lifecycle states for one ledger transaction row.
 *
 * Attributes: ACTIVE: The row participates in every default list, every tax
 * aggregation, and every readiness check. The only state in which
 * `update_manual_transaction` accepts a mutation. ARCHIVED: Operator chose to
 * remove the row from default attention without deleting it. Reversible.
 * STASHED: Operator parked the row pending classification or review.
 * Reversible. SPLIT: The row is the parent of an N-way split; its amount has
 * been redistributed into `N` child rows that now carry the active balance.
 * The parent is preserved for audit lineage. A SPLIT row is invisible to
 * default lists, tax aggregations, and readiness checks; only the
 * `merge_transactions` action can transition a SPLIT parent back to ARCHIVED
 * (never to ACTIVE).
 */
export type TransactionLifecycleState =
  "ACTIVE" | "ARCHIVED" | "STASHED" | "SPLIT";

